const { useState } = React;

function Order() {
  const price = 12000;
  const [quantity, setQuantity] = useState(1);
  const total = price * quantity;

  return (
    <section>
      <p>수량: {quantity}</p>
      <p>합계: {total}원</p>
      <button type="button" onClick={() => setQuantity(quantity + 1)}>증가</button>
      <button type="button" onClick={() => setQuantity(Math.max(1, quantity - 1))}>감소</button>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Order />);

